# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill - Windows-native PowerShell port of template.sh.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# Run:            pwsh -File wizard.ps1
# Unattended:     $env:WIZARD_NO_OPEN = '1'; @('pk_test_x','sk_test_y') | pwsh -File wizard.ps1
#                 (skips browser launch and reads answers from a pipe)
#
# Note: this file redefines `pause` inside its own scope so a profile function
# of the same name cannot hijack a stage.

$ErrorActionPreference = 'Stop'

# --------------------------------------------------------------------------
# Wizard library: delightful, consistent UX, identical across every wizard.
# --------------------------------------------------------------------------

$script:UseColor = -not [Console]::IsOutputRedirected
$script:EnvFile = if ($env:ENV_FILE) { $env:ENV_FILE } else { '.env' }
$script:TotalStages = 0
$script:StageIndex = 0
$script:WrittenEnv = @()
$script:WrittenSecret = @()
$script:Skipped = @()

function Write-Styled {
  param(
    [Parameter(Position = 0)][AllowEmptyString()][string]$Text = '',
    [Parameter(Position = 1)][string]$Color = 'Gray'
  )
  if ($script:UseColor) { Write-Host $Text -ForegroundColor $Color } else { Write-Output $Text }
}

# Read-WizardLine reads one line, from the console or from piped answers.
function Read-WizardLine {
  param([Parameter(Position = 0)][string]$Prompt = '')
  if ([Console]::IsInputRedirected) {
    [Console]::Out.Write($Prompt)
    $line = [Console]::In.ReadLine()
    if ($null -eq $line) { throw 'Input ended before the wizard completed.' }
    [Console]::Out.WriteLine()
    return $line
  }
  return Read-Host $Prompt
}

# Clear-Step wipes the terminal so only the current step is on screen.
# No-op when output is redirected, so piped logs stay readable.
function Clear-Step {
  if ($script:UseColor) { Clear-Host }
}

# banner "Title" shows the opening frame: what this wizard does.
function banner {
  param([Parameter(Position = 0)][string]$Title)
  Clear-Step
  Write-Styled ''
  Write-Styled "  $Title" 'Cyan'
  Write-Styled "  $($script:TotalStages) stages" 'DarkGray'
  Write-Styled ''
  Write-Styled '  You drive the browser; this wizard tells you exactly what to do and' 'DarkGray'
  Write-Styled '  captures the values you copy back. Stop any time with Ctrl-C and re-run' 'DarkGray'
  Write-Styled '  later, since it remembers values already saved.' 'DarkGray'
  pause 'Ready to start?'
}

# stage "Name" clears the screen, then announces a stage and shows progress.
function stage {
  param([Parameter(Position = 0)][string]$Name)
  Clear-Step
  $script:StageIndex++
  Write-Styled ('  > Stage {0}/{1} - {2}' -f $script:StageIndex, $script:TotalStages, $Name) 'Cyan'
}

# say "..." prints a plain instruction line.
function say { param([Parameter(Position = 0)][AllowEmptyString()][string]$Text) Write-Styled "  $Text" }
# step "..." is a numbered-feeling action the human takes in the browser.
function step { param([Parameter(Position = 0)][AllowEmptyString()][string]$Text) Write-Styled "  - $Text" 'Cyan' }
function note { param([Parameter(Position = 0)][AllowEmptyString()][string]$Text) Write-Styled "  $Text" 'DarkGray' }
function warn { param([Parameter(Position = 0)][AllowEmptyString()][string]$Text) Write-Styled "  ! $Text" 'Yellow' }

# open_url URL opens it in the human's browser. WIZARD_NO_OPEN=1 disables it.
function open_url {
  param([Parameter(Position = 0)][string]$Url)
  Write-Styled "  -> opening $Url" 'Green'
  if ($env:WIZARD_NO_OPEN) { return }
  try {
    Start-Process $Url | Out-Null
  } catch {
    warn "couldn't open a browser, so visit it manually: $Url"
  }
}

# pause "msg" waits for the human to confirm they've done the manual part.
function pause {
  param([Parameter(Position = 0)][string]$Message = 'Press Enter to continue')
  try { [void](Read-WizardLine "  $Message ") } catch { Write-Output '' }
}

# confirm "question" is a y/N gate; returns success on yes.
function confirm {
  param([Parameter(Position = 0)][string]$Question)
  try { $reply = Read-WizardLine "  ? $Question [y/N] " } catch { return $false }
  return ($reply -match '^[Yy]')
}

# Get-EnvValue KEY returns the current value of KEY in ENV_FILE, if any.
function Get-EnvValue {
  param([Parameter(Mandatory)][string]$Key)
  if (-not (Test-Path -LiteralPath $script:EnvFile -PathType Leaf)) { return $null }
  $pattern = '^' + [regex]::Escape($Key) + '='
  $line = [IO.File]::ReadAllLines($script:EnvFile) | Where-Object { $_ -match $pattern } | Select-Object -Last 1
  if (-not $line) { return $null }
  $value = $line.Substring($line.IndexOf('=') + 1)
  if ($value.Length -ge 2 -and $value.StartsWith("'") -and $value.EndsWith("'")) {
    return $value.Substring(1, $value.Length - 2).Replace("'\''", "'")
  }
  if ($value.Length -ge 2 -and $value.StartsWith('"') -and $value.EndsWith('"')) {
    $value = $value.Substring(1, $value.Length - 2)
    if ($value -match '[\\$"]') { return $null }   # escapes, $ or ": can't decode safely; ask again
    return $value
  }
  return $value
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it).
function ask {
  param([Parameter(Mandatory, Position = 0)][string]$Key, [Parameter(Position = 1)][string]$Prompt)
  $current = Get-EnvValue $Key
  $label = "  $Prompt"
  if ($current) { $label += ' [Enter keeps current] ' } else { $label += ' ' }
  $answer = Read-WizardLine $label
  if ([string]::IsNullOrEmpty($answer)) {
    if (-not $current) { return }
    $answer = $current
  }
  Set-Variable -Name $Key -Value $answer -Scope Script
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
function ask_secret {
  param([Parameter(Mandatory, Position = 0)][string]$Key, [Parameter(Position = 1)][string]$Prompt)
  $current = Get-EnvValue $Key
  $label = if ($current) { "  $Prompt [Enter keeps current] " } else { "  $Prompt " }
  if ([Console]::IsInputRedirected) {
    $answer = Read-WizardLine $label
  } else {
    $secure = Read-Host -Prompt $label -AsSecureString
    $answer = [System.Net.NetworkCredential]::new('', $secure).Password
  }
  if ([string]::IsNullOrEmpty($answer)) {
    if (-not $current) { return }
    $answer = $current
  }
  Set-Variable -Name $Key -Value $answer -Scope Script
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE when missing.
function write_env {
  param([Parameter(Mandatory, Position = 0)][string]$Key, [Parameter(Position = 1)][AllowEmptyString()][string]$Value = '')
  $escaped = $Value.Replace("'", "'\''")
  $line = "$Key='$escaped'"
  $pattern = '^' + [regex]::Escape($Key) + '='
  $lines = @()
  if (Test-Path -LiteralPath $script:EnvFile -PathType Leaf) {
    $lines = @([IO.File]::ReadAllLines($script:EnvFile) | Where-Object { $_ -notmatch $pattern })
  }
  $utf8 = New-Object System.Text.UTF8Encoding($false)
  [IO.File]::WriteAllLines((Join-Path (Get-Location) $script:EnvFile), [string[]]($lines + $line), $utf8)
  Set-Variable -Name $Key -Value $Value -Scope Script
  $script:WrittenEnv += $Key
  Write-Styled "  OK wrote $Key -> $($script:EnvFile)" 'Green'
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
function set_secret {
  param([Parameter(Mandatory, Position = 0)][string]$Name, [Parameter(Position = 1)][AllowEmptyString()][string]$Value = '')
  $gh = Get-Command gh -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($gh) {
    & $gh.Source auth status *> $null
    if ($LASTEXITCODE -eq 0) {
      $previous = $OutputEncoding
      $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
      try { $Value | & $gh.Source secret set $Name 2>&1 | Out-Null } catch { $null = $_ } finally { $OutputEncoding = $previous }
      if ($LASTEXITCODE -eq 0) {
        $script:WrittenSecret += $Name
        Write-Styled "  OK set GitHub secret $Name" 'Green'
        return
      }
    }
  }
  $script:Skipped += "GitHub secret $Name (set it manually: gh secret set $Name)"
  warn "skipped GitHub secret ${Name}: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
function set_var {
  param([Parameter(Mandatory, Position = 0)][string]$Name, [Parameter(Position = 1)][AllowEmptyString()][string]$Value = '')
  $gh = Get-Command gh -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($gh) {
    & $gh.Source auth status *> $null
    if ($LASTEXITCODE -eq 0) {
      & $gh.Source variable set $Name --body $Value 2>&1 | Out-Null
      if ($LASTEXITCODE -eq 0) {
        Write-Styled "  OK set GitHub variable $Name" 'Green'
        return
      }
    }
  }
  $script:Skipped += "GitHub variable $Name"
  warn "skipped GitHub variable $Name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
function finish {
  Clear-Step
  Write-Styled ''
  Write-Styled '  OK Setup complete' 'Green'
  if ($script:WrittenEnv.Count -gt 0) {
    note "wrote $($script:WrittenEnv.Count) value(s) to $($script:EnvFile): $($script:WrittenEnv -join ' ')"
  }
  if ($script:WrittenSecret.Count -gt 0) {
    note "set $($script:WrittenSecret.Count) GitHub secret(s): $($script:WrittenSecret -join ' ')"
  }
  if ($script:Skipped.Count -gt 0) {
    Write-Styled ''
    warn 'still to do by hand:'
    foreach ($item in $script:Skipped) { note "  - $item" }
  }
  Write-Styled ''
}

# --------------------------------------------------------------------------
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set $script:TotalStages to match the stages you
# write. Keep every stage inside run_wizard and the last line as is.
# --------------------------------------------------------------------------

function run_wizard {

  $script:TotalStages = 1

  banner 'Stripe setup'

  # -- Example stage: replace with your real steps ---------------------------
  stage 'Stripe: API keys'
  say "We'll grab your Stripe test keys and store them for local dev + CI."
  open_url 'https://dashboard.stripe.com/test/apikeys'
  step 'On the API keys page, copy the Publishable key (starts pk_test_).'
  ask STRIPE_PUBLISHABLE_KEY 'Paste the publishable key:'
  step "Click 'Reveal test key' on the Secret key row, then copy it."
  ask_secret STRIPE_SECRET_KEY 'Paste the secret key:'
  write_env STRIPE_PUBLISHABLE_KEY $script:STRIPE_PUBLISHABLE_KEY
  write_env STRIPE_SECRET_KEY $script:STRIPE_SECRET_KEY
  set_secret STRIPE_SECRET_KEY $script:STRIPE_SECRET_KEY   # CI needs this one
  # --------------------------------------------------------------------------

  finish
}

run_wizard
